#!/usr/bin/env node
/**
 * build-bundle-dem-jp.js
 *
 * 国土地理院 標高タイル (z=14 PNG, tmp/tiles/dem5a_png + dem_png) から
 * 日本全国の grid 標高データを生成し data/dem-jp.js として出力。
 *
 * 用途:
 *   map-matcher.js worker の loadDem handler が受信 → _demData として保持
 *   → _routeDistance3D で道路区間の Δh 加味・GPS 高度照合に使用
 *
 * 形式: window.DEM_JP = { bbox, gridSize, numLat, numLng, altB64 }
 *   alt: Int16Array (標高 m, sea level 基準, 海/データ無は 0)
 *
 * 設定:
 *   BBOX        日本全国 [minLat, minLng, maxLat, maxLng]
 *   GRID_SIZE   度数 (0.02° ≒ 2km / cell)
 *
 * 使い方:
 *   node scripts/build-bundle-dem-jp.js              # 全国
 *   node scripts/build-bundle-dem-jp.js --test       # 小範囲 (tokyo bbox 試運転)
 *
 * © 国土地理院 (出典明示で商用可)
 */

const fs = require('fs');
const path = require('path');
const createDem = require('./dem-lookup.js');

const PROJECT_ROOT = path.join(__dirname, '..');
const OUT = path.join(PROJECT_ROOT, 'data', 'dem-jp.js');

const TEST_MODE = process.argv.includes('--test');

// 日本全国 bbox (沖縄南方〜北海道北端・小笠原東端を含む)
const BBOX_JP = [20.0, 122.0, 46.0, 154.0];
// テスト用: tokyo + kanagawa あたり (cells が少なく短時間で確認)
const BBOX_TEST = [35.0, 139.0, 36.0, 140.5];

const BBOX = TEST_MODE ? BBOX_TEST : BBOX_JP;
// ★ grid size 選定:
//   DEM_JP の用途は (a) GPS 高度と地域標高照合で誤マッチ判定 (b) 長距離道路の Δh 加味
//   2km grid だと短距離道路 (~数百m) では両端が同 cell → Δh=0 で無意味
//   5km grid で地域単位の標高 trend (海岸/平地/山岳) を捉えるのが現実的
//   短距離道路の勾配は roads bitmap の incline (2bit) フィールドで代替済
//   全国 333k cells = Int16 666KB base64 ~890KB ≒ 1MB レベル
const GRID_SIZE = 0.05; // 約 5.5km/cell (lat)・現実的サイズと精度のバランス

const numLat = Math.ceil((BBOX[2] - BBOX[0]) / GRID_SIZE);
const numLng = Math.ceil((BBOX[3] - BBOX[1]) / GRID_SIZE);
const totalCells = numLat * numLng;

console.log(`[DEM] mode: ${TEST_MODE ? 'TEST (tokyo area)' : 'FULL (Japan)'}`);
console.log(`[DEM] bbox: lat[${BBOX[0]}..${BBOX[2]}] lng[${BBOX[1]}..${BBOX[3]}]`);
console.log(
  `[DEM] grid: ${numLat} × ${numLng} = ${totalCells} cells @ ${GRID_SIZE}° (~${(GRID_SIZE * 111).toFixed(1)}km)`
);
console.log(`[DEM] estimated Int16 size: ${((totalCells * 2) / 1024 / 1024).toFixed(2)} MB`);

const dem = createDem({ zoom: 14 });
const alt = new Int16Array(totalCells);
let valid = 0;
const t0 = Date.now();
const logEvery = Math.max(1, Math.floor(totalCells / 50));

for (let y = 0; y < numLat; y++) {
  const lat = BBOX[0] + (y + 0.5) * GRID_SIZE;
  for (let x = 0; x < numLng; x++) {
    const lng = BBOX[1] + (x + 0.5) * GRID_SIZE;
    const idx = y * numLng + x;
    const h = dem.elev(lat, lng);
    if (typeof h === 'number' && !isNaN(h)) {
      alt[idx] = Math.max(-32768, Math.min(32767, Math.round(h)));
      valid++;
    } else {
      alt[idx] = 0; // 海 or タイル無
    }
    if ((idx + 1) % logEvery === 0) {
      const pct = (((idx + 1) / totalCells) * 100).toFixed(1);
      const elapsed = ((Date.now() - t0) / 1000).toFixed(1);
      const eta = ((((Date.now() - t0) / (idx + 1)) * (totalCells - idx - 1)) / 1000).toFixed(0);
      console.log(
        `[DEM]   ${idx + 1}/${totalCells} (${pct}%) valid=${valid} elapsed=${elapsed}s eta=${eta}s`
      );
    }
  }
}

const buf = Buffer.from(alt.buffer);
const altB64 = buf.toString('base64');

const outFile = TEST_MODE ? path.join(PROJECT_ROOT, 'data', 'dem-jp.test.js') : OUT;

const json = JSON.stringify({
  bbox: BBOX,
  gridSize: GRID_SIZE,
  numLat,
  numLng,
  altB64,
});

const content = `// Auto-generated by scripts/build-bundle-dem-jp.js
// Source: 国土地理院 標高タイル PNG (5mDEM + 10mDEM, z=14) → ${GRID_SIZE}° grid sampling
// Generated: ${new Date().toISOString()}
// Grid: ${numLat} × ${numLng} = ${totalCells} cells, valid=${valid} (${((valid / totalCells) * 100).toFixed(1)}%)
// Format: window.DEM_JP = { bbox, gridSize, numLat, numLng, altB64 }
//   alt: Int16Array (標高 m, sea level 基準, 海/データ無は 0)
// © 国土地理院 (出典明示で商用可)
window.DEM_JP = ${json};
`;

fs.writeFileSync(outFile, content);
const stat = fs.statSync(outFile);
console.log(`[DEM] wrote ${outFile} (${(stat.size / 1024 / 1024).toFixed(2)} MB)`);
console.log(`[DEM] lookup stats:`, dem.stats());
console.log(`[DEM] total time: ${((Date.now() - t0) / 1000).toFixed(1)}s`);
